question.solution:
class MyQueue:
    def __init__(self):
        self.in_stack = []
        self.out_stack = []

    def push(self, x):
        self.in_stack.append(x)
        return self

    def _shift(self):
        if not self.out_stack:
            while self.in_stack:
                self.out_stack.append(self.in_stack.pop())

    def pop(self):
        self._shift()
        if not self.out_stack:
            raise IndexError('队列为空')
        return self.out_stack.pop()

    def peek(self):
        self._shift()
        if not self.out_stack:
            raise IndexError('队列为空')
        return self.out_stack[-1]

    def empty(self):
        return not self.in_stack and not self.out_stack

    def size(self):
        return len(self.in_stack) + len(self.out_stack)


q = MyQueue()
q.push(1)
q.push(2)
print(q.peek(), q.pop(), q.empty(), q.size())

